<template>
  <div
    class="product-thumbnail"
    @click="openProduct"
  >
    <img
      :src="product.thumbnail_url"
      :alt="product.name"
      class="product-thumbnail__image"
    />
    <div class="product-thumbnail__content">
      <h5 class="product-thumbnail__content__title">
        {{ formattedProductName }}
      </h5>
      <h6 class="product-thumbnail__content__subtitle">
        {{ product.subtitle }}
      </h6>
      <ul class="product-thumbnail__content__attributes">
        <li
          v-for="type in types"
          :key="type"
        >
          <span v-html="type.icon"></span>
          <span>{{ product[type.key].name }}</span>
        </li>
      </ul>
      <div v-if="product.tags?.length > 0" class="product-thumbnail__content__tags">
        <a
          v-for="tag in product.tags"
          :key="tag.id"
          :href="`${siteUrl}/travel?search=${tag.name}`"
        >
          {{ tag.name }}
        </a>
      </div>
    </div>
  </div>
</template>

