<style lang="scss" scoped>
.product-thumbnail {
  @apply rounded-lg bg-white border border-border-20 lining-nums cursor-pointer
         hover:border-border-30 hover:-translate-y-2 transition-all duration-500;

  &__image {
    @apply w-full h-[200px] object-cover rounded-t-lg tablet:h-[220px] xs:h-[245px];
  }

  &__content {
    @apply p-3;

    &__title {
      @apply text-label-m font-semibold text-content-80 whitespace-pre-line overflow-hidden mb-2;
    }

    &__subtitle {
      @apply text-label-s truncate mb-4 text-content-70;
    }

    &__attributes {
      @apply flex flex-wrap justify-start gap-x-3 text-content-80;
      li {
        @apply flex items-center font-semibold text-label-xs;
      }
    }

    &__tags {
      @apply flex items-center flex-wrap gap-2 text-nowrap mt-3;
      a {
        @apply text-label-xs text-content-50 no-underline rounded-[2px] px-1.5 bg-bg-10
               hover:text-content-0 hover:bg-main-brown;
      }
    }
  }
}
</style>
